source.css:
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #1f2937, #0f172a);
  font-family: system-ui, sans-serif;
  color: #e5e7eb;
}

.card {
  max-width: 34rem;
  padding: 2.5rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  text-align: center;
}

button {
  padding: 0.6rem 1.2rem;
  border: 0;
  border-radius: 8px;
  background: #3d7dfd;
  color: #fff;
  font-size: 1rem;
  cursor: pointer;
}

